        "signature": "image: dspy.Image, class_labels: List[str] -> probabilities: Dict[str, float]",
        "inputs": {"image": "https://example.com/dog.jpg", "class_labels": ["dog", "cat", "bird"]},
        "key_output": "probabilities",
